        function fullSheetAnalysis() {
            var data = JSON.stringify((spreadsheet.sheets[spreadsheet.activeSheetIndex].ranges)[0].dataSource);
            let query = 'Analyze the full data in this data. ' + data;
            let aiOutput = geminiModel(query);
            aiOutput.then((result) => {
                result = markdownToPlainText(result);
                renderAssistView(result);
                sidebarObj.show();
            });
        }

        function formulaValidate() {
            const selectedCell = spreadsheet.sheets[spreadsheet.activeSheetIndex].selectedRange;
            let isFormulaAvailable = false;
            if (!ej.base.isNullOrUndefined(selectedCell)) {
                spreadsheet.getData(selectedCell).then((data) => {
                    const currentCells = Array.from(data.keys());
                    let query = 'Validate the below formulae and provide me the problem in it. Strictly provide the data for each validated response in a flat JSON with fields `cell` to hold the spreadsheet cell value and `response` to hold the problem and solution.';
                    for (let a = 0; a < currentCells.length; a++) {
                        const cellFormula = data.get(currentCells[a]).formula;
                        if (!ej.base.isNullOrUndefined(cellFormula)) {
                            isFormulaAvailable = true;
                            query += 'Spreadsheet cell - ' + currentCells[a] + ' - Formula - ' + cellFormula + ' - ' + processString(cellFormula);
                        }
                    }
                    if (isFormulaAvailable) {
                        let aiOutput = geminiModel(query);
                        aiOutput.then((result) => {
                            let cleanedResponseText = result.replace(/^```json\n|```\s*$/g, '').trim();
                            cleanedResponseText = cleanedResponseText.split("```")[0].trim();
                            const responseJson = JSON.parse(cleanedResponseText);
                            for (let a = 0; a < responseJson.length; a++) {
                                spreadsheet.updateCell({ notes: (responseJson[a]).response }, (responseJson[a]).cell);
                            }
                        });
                    }
                });
            }
        }

        function renderAssistView(response) {
            if (ej.base.isNullOrUndefined(aiinstance)) {
                aiinstance = new ej.interactivechat.AIAssistView({
                    promptPlaceholder: "Type your prompt for assistance...",
                    prompts: [{ prompt: '', response: response }]
                });
                aiinstance.appendTo('#defaultAIAssistView');
            } else {
                aiinstance.prompts = [{ prompt: '', response: response }];
            }
        }

        function processString(forumlaString) {
            let processedString = '';
            const regex = /\(([^)]+)\)/g;
            let matches = [];
            let match;
            while ((match = regex.exec(forumlaString)) !== null) {
                let text = match[1];
                matches = text.split(/[:+\-*=/]/).map(s => s.trim()).filter(s => s !== '');
            }
            if (ej.base.isNullOrUndefined(matches) || matches.length <= 0) {
                matches = forumlaString.split(/[:+\-*=/]/).map(s => s.trim()).filter(s => s !== '');
            }
            if (matches.length > 0) {
                for (let i = 0; i < matches.length; i++) {
                    let { rowIndex, columnIndex } = cellAddressToIndexes(matches[i]);
                    if (rowIndex != null && columnIndex != null) {
                        processedString += 'Value of the cell ' + matches[i] + ' is ' + ej.spreadsheet.getCell(rowIndex, columnIndex, spreadsheet.sheets[spreadsheet.activeSheetIndex]).value + '/n';
                    }
                }
            }
            return processedString;
        }

        function cellAddressToIndexes(cellAddress) {
            const match = cellAddress.match(/^([A-Z]+)(\d+)$/);
            if (!match) {
                let rowIndex = null;
                let columnIndex = null;
                return { rowIndex, columnIndex };
            }
            const columnLetters = match[1];
            const rowNumber = parseInt(match[2], 10);
            let columnIndex = 0;
            for (let i = 0; i < columnLetters.length; i++) {
                columnIndex = columnIndex * 26 + (columnLetters.charCodeAt(i) - 'A'.charCodeAt(0));
            }
            const rowIndex = rowNumber - 1;
            return { rowIndex, columnIndex };
        }

        function markdownToPlainText(markdown) {
            markdown = markdown.replace(/^###### (.+)$/gm, '<h6>$1</h6>');
            markdown = markdown.replace(/^##### (.+)$/gm, '<h5>$1</h5>');
            markdown = markdown.replace(/^#### (.+)$/gm, '<h4>$1</h4>');
            markdown = markdown.replace(/^### (.+)$/gm, '<h3>$1</h3>');
            markdown = markdown.replace(/^## (.+)$/gm, '<h2>$1</h2>');
            markdown = markdown.replace(/^# (.+)$/gm, '<h1>$1</h1>');

            // Replace bold and italic
            markdown = markdown.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
            markdown = markdown.replace(/\*(.+?)\*/g, '<em>$1</em>');

            // Replace lists
            markdown = markdown.replace(/^\* (.+)$/gm, '<ul>\n<li>$1</li>\n</ul>');
            markdown = markdown.replace(/^\d+\. (.+)$/gm, '<ol>\n<li>$1</li>\n</ol>');

            // Replace links
            markdown = markdown.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');

            // Replace line breaks with <br>
            markdown = markdown.replace(/\n/g, '<br>');

            // Replace empty lines with <p> tags
            markdown = markdown.replace(/(<br>){2,}/g, '</p>\n<p>');
            markdown = '<p>' + markdown + '</p>';
            return markdown;
        }
    }
